private val gate = Mutex()
private var state = State.Idle            // guarded by gate
suspend fun tryStart(): Boolean {
    if (!gate.tryLock()) return false     // balk: transition already running
    try {
        if (state != State.Idle) return false
        state = State.Running
        return true
    } finally {
        gate.unlock()
    }
}
